package com.example.stats.repository;

import com.example.stats.dto.UsageSummaryDto;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;

@Repository
public class StatsRepositoryImpl implements StatsRepository {
    private static final Logger log = LoggerFactory.getLogger(StatsRepositoryImpl.class);
    private final JdbcTemplate jdbcTemplate;

    public StatsRepositoryImpl(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public List<UsageSummaryDto> getUsageSummaryByAccountLast7Days() {
        String sql = "SELECT account_id, COUNT(*) AS total_requests, COUNT(DISTINCT user_id) AS active_users " +
                     "FROM requests WHERE created_at >= ? GROUP BY account_id";
        Timestamp sevenDaysAgo = Timestamp.from(Instant.now().minusSeconds(7 * 24 * 3600L));
        try {
            return jdbcTemplate.query(
                sql,
                new Object[] { sevenDaysAgo },
                (rs, rowNum) -> new UsageSummaryDto(
                    rs.getString("account_id"),
                    rs.getLong("total_requests"),
                    rs.getInt("active_users")
                )
            );
        } catch (DataAccessException e) {
            log.error("Failed to query usage summary for last 7 days", e);
            throw e;
        }
    }
}
