package com.example.stats.repository;

import com.example.stats.dto.UsageSummaryDto;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
@ActiveProfiles("test")
public class StatsRepositoryTest {
    @Autowired
    private StatsRepository statsRepository;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Test
    void getUsageSummaryByAccountLast7Days_excludesOlderThan7Days_and_groupsByAccount() {
        jdbcTemplate.update("CREATE TABLE IF NOT EXISTS requests (id varchar(100), account_id varchar(100), user_id varchar(100), created_at timestamp)");
        jdbcTemplate.update("DELETE FROM requests");

        // within 7 days
        Timestamp now = Timestamp.from(Instant.now());
        jdbcTemplate.update("INSERT INTO requests (id, account_id, user_id, created_at) VALUES (?, ?, ?, ?)", "r1", "acctA", "user1", now);
        jdbcTemplate.update("INSERT INTO requests (id, account_id, user_id, created_at) VALUES (?, ?, ?, ?)", "r2", "acctA", "user2", now);
        jdbcTemplate.update("INSERT INTO requests (id, account_id, user_id, created_at) VALUES (?, ?, ?, ?)", "r3", "acctB", "user3", now);

        // older than 7 days
        Timestamp old = Timestamp.from(Instant.now().minusSeconds(8 * 24 * 3600L));
        jdbcTemplate.update("INSERT INTO requests (id, account_id, user_id, created_at) VALUES (?, ?, ?, ?)", "r4", "acctA", "user4", old);

        List<UsageSummaryDto> list = statsRepository.getUsageSummaryByAccountLast7Days();

        assertThat(list).hasSize(2);
        UsageSummaryDto a = list.stream().filter(x -> "acctA".equals(x.getAccountId())).findFirst().orElse(null);
        UsageSummaryDto b = list.stream().filter(x -> "acctB".equals(x.getAccountId())).findFirst().orElse(null);

        assertThat(a).isNotNull();
        assertThat(a.getTotalRequests()).isEqualTo(2); // old row excluded
        assertThat(a.getActiveUsers()).isEqualTo(2);

        assertThat(b).isNotNull();
        assertThat(b.getTotalRequests()).isEqualTo(1);
        assertThat(b.getActiveUsers()).isEqualTo(1);
    }
}
